before_layer_change_gcode:
{if layer_num == 1}
{if is_extruder_used[0] and is_extruder_used[1]}
; Desired bed temperatures: {bed_temperature[0]} and {bed_temperature[1]}
M140 S{bed_temperature[0] > bed_temperature[1] ? bed_temperature[0] : bed_temperature[1]}
{else}
{if is_extruder_used[0]}
M140 S{bed_temperature[0]}
{else}
M140 S{bed_temperature[1]}
{endif}
{endif}
{endif}

machine_start_gcode:
M190
G10

M83          ; Relative Extruder mode

M98 P"/sys/prepare-to-print.g" {if is_extruder_used[0]}H{first_layer_temperature[0]} B{first_layer_bed_temperature[0]} T"{filament_type[0]}"{endif} {if is_extruder_used[1]} I{first_layer_temperature[1]} C{first_layer_bed_temperature[1]} U"{filament_type[1]}"{endif}

T{initial_tool}
